//! Parity tests for the MegaTTS3 DiT, sampler, and relative-position encoder.
//!
//! Fixtures live in `testdata/megatts3_dit/`, regenerated by
//! `tools/gen_megatts3_dit_fixtures.py` from the unmodified PyTorch classes.
//! Each case replays the exact Gaussian draws `torch.randn` produced (draw 0
//! is the initial latent, then one per step), so the stochastic sampler is
//! deterministic here. A real converted checkpoint can be gated in with
//! TURBOSPARK_DIT_MODEL (dir with `model.safetensors`) and
//! TURBOSPARK_DIT_GOLDEN (dir with the `r_*.npy` traces from
//! `--real-src`); both are skipped when unset. Tests never download.

use std::path::{Path, PathBuf};

use super::dit::{Dit, DitConfig};
use super::sampler::{amo_step, sample, sway_schedule, SamplerParams};
use turbospark_model_io::safetensors::SafetensorsFile;

fn fixture(dir: &Path, name: &str) -> PathBuf {
    dir.join(name)
}

fn testdata() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("testdata/megatts3_dit")
}

/// Reads a little-endian `<f4` or `<i4` C-order `.npy` as f32 / i32.
fn read_npy(path: &Path) -> (Vec<usize>, Vec<u8>, bool) {
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    assert!(
        header.contains("'fortran_order': False"),
        "fortran-ordered npy: {header}"
    );
    let is_int = header.contains("'<i4'");
    assert!(
        is_int || header.contains("'<f4'"),
        "unsupported dtype: {header}"
    );
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    (shape, bytes[10 + header_len..].to_vec(), is_int)
}

pub(super) fn f32s(dir: &Path, name: &str) -> Vec<f32> {
    let (_, data, is_int) = read_npy(&fixture(dir, name));
    assert!(!is_int, "{name} is int");
    data.chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

pub(super) fn i32s(dir: &Path, name: &str) -> Vec<i32> {
    let (_, data, is_int) = read_npy(&fixture(dir, name));
    assert!(is_int, "{name} is not int");
    data.chunks_exact(4)
        .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

pub(super) fn max_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0, f32::max)
}

fn load_tiny() -> Dit {
    let text = std::fs::read_to_string(testdata().join("tiny_config.json")).unwrap();
    let cfg = DitConfig::from_json(&serde_json::from_str(&text).unwrap()).unwrap();
    let file = SafetensorsFile::open(&testdata().join("tiny_weights.safetensors")).unwrap();
    Dit::load(cfg, &file).unwrap()
}

/// Runs the whole per-case comparison against `dir/{tag}_*.npy`.
fn check_case(dit: &Dit, dir: &Path, tag: &str, steps: usize, p_w: f32, t_w: f32, tol: f32) {
    let phone = i32s(dir, &format!("{tag}_phone.npy"));
    let tone = i32s(dir, &format!("{tag}_tone.npy"));
    let mel2ph = i32s(dir, &format!("{tag}_mel2ph.npy"));
    let prompt = f32s(dir, &format!("{tag}_prompt.npy"));
    let ch = dit.config().channels;
    let frames = mel2ph.len() / 4;

    let enc = dit.phone_encoding(&phone, &tone).unwrap();
    let enc_diff = max_diff(&enc, &f32s(dir, &format!("{tag}_ph_enc.npy")));
    let ling = dit.ling(&phone, &tone, &mel2ph, frames).unwrap();
    let ling_diff = max_diff(&ling, &f32s(dir, &format!("{tag}_x_ling.npy")));
    println!("{tag}: ph_enc {enc_diff:e} x_ling {ling_diff:e}");
    assert!(enc_diff < tol, "{tag} phone encoder diff {enc_diff}");
    assert!(ling_diff < tol, "{tag} x_ling diff {ling_diff}");

    let cond = dit.prepare(&phone, &tone, &mel2ph, &prompt).unwrap();
    assert_eq!(
        (cond.frames, cond.prompt_frames),
        (frames, prompt.len() / ch)
    );

    let draws: Vec<Vec<f32>> = (0..=steps)
        .map(|i| f32s(dir, &format!("{tag}_draw_{i:02}.npy")))
        .collect();
    // First step: x is the initial draw, sigma is the first schedule point.
    let vel = dit
        .velocity(&cond, &draws[0], sway_schedule(steps)[0], p_w, t_w)
        .unwrap();
    let vel_diff = max_diff(&vel, &f32s(dir, &format!("{tag}_vel_first.npy")));
    println!("{tag}: velocity {vel_diff:e}");
    assert!(vel_diff < tol, "{tag} first velocity diff {vel_diff}");

    let mut it = draws.iter();
    let x = sample(
        dit,
        &cond,
        SamplerParams { steps, p_w, t_w },
        &mut |out: &mut [f32]| {
            out.copy_from_slice(it.next().expect("more draws than the reference made"))
        },
    )
    .unwrap();
    assert!(
        it.next().is_none(),
        "sampler drew fewer times than the reference"
    );
    let x_diff = max_diff(&x, &f32s(dir, &format!("{tag}_x_final.npy")));
    println!("{tag}: final latent {x_diff:e}");
    assert!(x_diff < tol, "{tag} final latent diff {x_diff}");
}

#[test]
fn tiny_matches_pytorch_reference() {
    let dit = load_tiny();
    // Case b has fewer phones than the relative-attention window + 1.
    check_case(&dit, &testdata(), "a", 4, 1.4, 3.0, 2e-5);
    check_case(&dit, &testdata(), "b", 3, 2.0, 2.5, 2e-5);
}

#[test]
fn sway_schedule_endpoints_and_shape() {
    for steps in [1usize, 2, 7, 32] {
        let s = sway_schedule(steps);
        assert_eq!(s.len(), steps + 1);
        assert_eq!(s[0], 0.0);
        assert!((s[steps] - 1.0).abs() < 1e-6, "ends at {}", s[steps]);
        assert!(s.windows(2).all(|w| w[1] > w[0]), "not increasing: {s:?}");
    }
    // Sway with coefficient -1 maps t to 1 - cos(pi t / 2).
    let s = sway_schedule(4);
    assert!((s[2] - (1.0 - (std::f32::consts::FRAC_PI_2 * 0.5).cos())).abs() < 1e-6);
}

#[test]
fn amo_final_step_is_a_plain_euler_step() {
    // At t_next = 1 the overshoot clamps to 1: a = 1 and b = 0, so the noise
    // is multiplied away and z' = z + (1 - t) * v.
    let z = [0.5f32, -1.0];
    let v = [2.0f32, 4.0];
    let noise = [1.0e6f32, -1.0e6];
    let out = amo_step(&z, 0.75, 1.0, &v, &noise);
    assert_eq!(out, vec![0.5 + 0.25 * 2.0, -1.0 + 0.25 * 4.0]);
}

#[test]
fn amo_overshoot_formula() {
    // s = 0.5, t = 0.25: o = 0.5 + 3 * 0.25 = 1.25 -> clamped to 1.
    let out = amo_step(&[0.0], 0.25, 0.5, &[1.0], &[2.0]);
    let (a, b) = (0.5f32, 0.5f32); // a = s / o, b = sqrt((1 - s)^2 - (a (1 - o))^2)
    assert!((out[0] - (a * (0.75 * 1.0) + b * 2.0)).abs() < 1e-6);
    // Interior overshoot: s = 0.2, t = 0.1 -> o = 0.5.
    let out = amo_step(&[1.0], 0.1, 0.2, &[2.0], &[-1.0]);
    let (o, s) = (0.5f32, 0.2f32);
    let a = s / o;
    let b = ((1.0 - s).powi(2) - (a * (1.0 - o)).powi(2)).sqrt();
    assert!((out[0] - (a * (1.0 + (o - 0.1) * 2.0) - b)).abs() < 1e-6);
}

#[test]
fn sampler_validates_arguments() {
    let dit = load_tiny();
    let dir = testdata();
    let cond = dit
        .prepare(
            &i32s(&dir, "a_phone.npy"),
            &i32s(&dir, "a_tone.npy"),
            &i32s(&dir, "a_mel2ph.npy"),
            &f32s(&dir, "a_prompt.npy"),
        )
        .unwrap();
    let mut zeros = |out: &mut [f32]| out.fill(0.0);
    for bad in [
        SamplerParams {
            steps: 0,
            ..SamplerParams::default()
        },
        SamplerParams {
            steps: 5000,
            ..SamplerParams::default()
        },
        SamplerParams {
            p_w: f32::NAN,
            ..SamplerParams::default()
        },
        SamplerParams {
            t_w: f32::INFINITY,
            ..SamplerParams::default()
        },
    ] {
        assert!(
            sample(&dit, &cond, bad, &mut zeros).is_err(),
            "{bad:?} accepted"
        );
    }
}

#[test]
fn prepare_rejects_bad_inputs() {
    let dit = load_tiny();
    let dir = testdata();
    let phone = i32s(&dir, "a_phone.npy");
    let tone = i32s(&dir, "a_tone.npy");
    let mel2ph = i32s(&dir, "a_mel2ph.npy");
    let prompt = f32s(&dir, "a_prompt.npy");
    assert!(dit.prepare(&phone, &tone, &mel2ph, &prompt).is_ok());
    assert!(
        dit.prepare(&phone, &tone[1..], &mel2ph, &prompt).is_err(),
        "length mismatch"
    );
    assert!(
        dit.prepare(&[], &[], &mel2ph, &prompt).is_err(),
        "empty phones"
    );
    assert!(
        dit.prepare(&phone, &tone, &mel2ph[1..], &prompt).is_err(),
        "not a multiple of 4"
    );
    assert!(
        dit.prepare(&phone, &tone, &[], &prompt).is_err(),
        "empty mel2ph"
    );
    let long_prompt = vec![0.0f32; (mel2ph.len() / 4 + 1) * dit.config().channels];
    assert!(
        dit.prepare(&phone, &tone, &mel2ph, &long_prompt).is_err(),
        "prompt longer than output"
    );
    assert!(
        dit.prepare(&phone, &tone, &mel2ph, &prompt[1..]).is_err(),
        "ragged prompt"
    );
    let mut bad_tone = tone.clone();
    bad_tone[0] = dit.config().tone_vocab as i32;
    assert!(
        dit.prepare(&phone, &bad_tone, &mel2ph, &prompt).is_err(),
        "tone out of range"
    );
    let mut bad_phone = phone.clone();
    bad_phone[0] = 0; // the pad id
    assert!(
        dit.prepare(&bad_phone, &tone, &mel2ph, &prompt).is_err(),
        "pad token"
    );
    let mut bad_m = mel2ph.clone();
    bad_m[3] = phone.len() as i32 + 1;
    assert!(
        dit.prepare(&phone, &tone, &bad_m, &prompt).is_err(),
        "mel2ph past last phone"
    );
    // An empty prompt is legal: nothing is held fixed.
    assert!(dit.prepare(&phone, &tone, &mel2ph, &[]).is_ok());
}

#[test]
fn velocity_checks_latent_shape() {
    let dit = load_tiny();
    let dir = testdata();
    let cond = dit
        .prepare(
            &i32s(&dir, "a_phone.npy"),
            &i32s(&dir, "a_tone.npy"),
            &i32s(&dir, "a_mel2ph.npy"),
            &f32s(&dir, "a_prompt.npy"),
        )
        .unwrap();
    assert!(dit.velocity(&cond, &[0.0; 3], 0.5, 1.0, 1.0).is_err());
}

#[test]
fn rejects_bad_configs() {
    let text = std::fs::read_to_string(testdata().join("tiny_config.json")).unwrap();
    let good: serde_json::Value = serde_json::from_str(&text).unwrap();
    assert!(DitConfig::from_json(&good).is_ok());
    for (field, value) in [
        ("heads", serde_json::json!(5)),  // does not divide dim
        ("heads", serde_json::json!(32)), // head width 1 is odd (rotary needs pairs)
        ("layers", serde_json::json!(0)),
        ("layers", serde_json::json!(65)),
        ("dim", serde_json::json!(0)),
        ("dim", serde_json::json!(100_000)),
        ("time_freq_dim", serde_json::json!(3)),
        ("phone_vocab", serde_json::json!(1)),
        ("ph_kernel", serde_json::json!(4)), // even conv kernel
        ("ph_heads", serde_json::json!(5)),
    ] {
        let mut bad = good.clone();
        bad[field] = value.clone();
        assert!(
            DitConfig::from_json(&bad).is_err(),
            "{field}={value} accepted"
        );
    }
    let mut missing = good.clone();
    missing.as_object_mut().unwrap().remove("channels");
    assert!(DitConfig::from_json(&missing).is_err());
    DitConfig::megatts3().validate().unwrap();
}

#[test]
fn missing_tensor_is_an_error() {
    // The tiny file loaded under the shipped geometry must fail cleanly on
    // the first shape check rather than panic.
    let file = SafetensorsFile::open(&testdata().join("tiny_weights.safetensors")).unwrap();
    assert!(Dit::load(DitConfig::megatts3(), &file).is_err());
}

/// Real converted checkpoint vs PyTorch golden tensors for a short sequence.
#[test]
fn real_checkpoint_matches_pytorch() {
    let (Some(model_dir), Some(golden)) = (
        std::env::var_os("TURBOSPARK_DIT_MODEL"),
        std::env::var_os("TURBOSPARK_DIT_GOLDEN"),
    ) else {
        eprintln!("skipped: TURBOSPARK_DIT_MODEL / TURBOSPARK_DIT_GOLDEN not set");
        return;
    };
    let dit = Dit::open(Path::new(&model_dir)).unwrap();
    let tol: f32 = std::env::var("TURBOSPARK_DIT_TOL")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(2e-4);
    check_case(&dit, Path::new(&golden), "r", 3, 1.4, 3.0, tol);
}
